11	    /// Disallow duplicate names within font families.
12	    ///
13	    /// This rule checks the `font` and `font-family` properties for duplicate font names.
14	    ///
15	    /// This rule ignores var(--custom-property) variable syntaxes now.
16	    ///
17	    ///
18	    /// ## Examples
19	    ///
20	    /// ### Invalid
21	    ///
22	    /// ```css,expect_diagnostic
23	    /// a { font-family: "Lucida Grande", 'Arial', sans-serif, sans-serif; }
24	    /// ```
25	    ///
26	    /// ```css,expect_diagnostic
27	    /// a { font-family: 'Arial', "Lucida Grande", Arial, sans-serif; }
28	    /// ```
29	    ///
30	    /// ```css,expect_diagnostic
31	    /// a { FONT: italic 300 16px/30px Arial, " Arial", serif; }
32	    /// ```
33	    ///
34	    /// ### Valid
35	    ///
36	    /// ```css
37	    /// a { font-family: "Lucida Grande", "Arial", sans-serif; }
38	    /// ```
39	    ///
40	    /// ```css
41	    /// b { font: normal 14px/32px -apple-system, BlinkMacSystemFont, sans-serif; }
42	    /// ```
43	    pub NoDuplicateFontNames {
44	        version: "next",
45	        name: "noDuplicateFontNames",
46	        recommended: true,
47	        sources: &[RuleSource::Stylelint("font-family-no-duplicate-names")],
48	    }
49	}
