56	impl Rule for NoDuplicateFontNames {
57	    type Query = Ast<CssGenericProperty>;
58	    type State = RuleState;
59	    type Signals = Option<Self::State>;
60	    type Options = ();
61	
62	    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
63	        let node = ctx.query();
64	        let property_name = node.name().ok()?.text().to_lowercase();
65	
66	        let is_font_family = property_name == "font-family";
67	        let is_font = property_name == "font";
68	
69	        if !is_font_family && !is_font {
70	            return None;
71	        }
72	
73	        let mut unquoted_family_names: HashSet<String> = HashSet::new();
74	        let mut family_names: HashSet<String> = HashSet::new();
75	        let value_list = node.value();
76	        let font_families = if is_font {
77	            find_font_family(value_list)
78	        } else {
79	            value_list
80	                .into_iter()
81	                .filter_map(|v| match v {
82	                    AnyCssGenericComponentValue::AnyCssValue(value) => Some(value),
83	                    _ => None,
84	                })
85	                .collect()
86	        };
87	
88	        for css_value in font_families {
89	            match css_value {
90	                // A generic family name like `sans-serif` or unquoted font name.
91	                AnyCssValue::CssIdentifier(val) => {
92	                    let font_name = val.text();
93	
94	                    // check the case: "Arial", Arial
95	                    // we ignore the case of the font name is a keyword(context: https://github.com/stylelint/stylelint/issues/1284)
96	                    // e.g "sans-serif", sans-serif
97	                    if family_names.contains(&font_name) && !is_font_family_keyword(&font_name) {
98	                        return Some(RuleState {
99	                            value: font_name,
100	                            span: val.range(),
101	                        });
102	                    }
103	
104	                    // check the case: sans-self, sans-self
105	                    if unquoted_family_names.contains(&font_name) {
106	                        return Some(RuleState {
107	                            value: font_name,
108	                            span: val.range(),
109	                        });
110	                    }
111	                    unquoted_family_names.insert(font_name);
112	                }
113	                // A font family name. e.g "Lucida Grande", "Arial".
114	                AnyCssValue::CssString(val) => {
115	                    let normalized_font_name: String = val
116	                        .text()
117	                        .chars()
118	                        .filter(|&c| c != '\'' && c != '\"' && !c.is_whitespace())
119	                        .collect();
120	
121	                    if family_names.contains(&normalized_font_name)
122	                        || unquoted_family_names.contains(&normalized_font_name)
123	                    {
124	                        return Some(RuleState {
125	                            value: normalized_font_name,
126	                            span: val.range(),
127	                        });
128	                    }
129	                    family_names.insert(normalized_font_name);
130	                }
131	                _ => continue,
132	            }
133	        }
134	        None
135	    }
136	
137	    fn diagnostic(_: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
138	        let span = state.span;
139	        Some(
140	            RuleDiagnostic::new(
141	                rule_category!(),
142	                span,
143	                markup! {
144	                    "Duplicate font names are redundant and unnecessary: "<Emphasis>{ state.value }</Emphasis>
145	                },
146	            )
147	            .note(markup! {
148	                "Remove duplicate font names within the property"
149	            }),
150	        )
151	    }
