use biome_console::markup;
use biome_css_syntax::{
    AnyCssDimension, CssFunction, CssGenericProperty, CssQueryFeaturePlain, CssSyntaxKind,
};
use biome_rowan::{AstNode, TextRange};

declare_rule! {
    /// Disallow unknown CSS units.
    ///
    /// For details on known CSS units, see the [MDN web docs](https://developer.mozilla.org/en-US/docs/Learn/CSS/Building_blocks/Values_and_units#lengths).
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```css,expect_diagnostic
    /// a {
    ///   width: 10pixels;
    /// }
    /// ```
    ///
    /// ```css,expect_diagnostic
    /// a {
    ///   width: calc(10px + 10pixels);
    /// }
    /// ```
    ///
    /// ### Valid
    ///
    /// ```css
    /// a {
    ///   width: 10px;
    /// }
    /// ```
    ///
    /// ```css
    /// a {
    ///   width: 10Px;
    /// }
    /// ```
    ///
    /// ```css
    /// a {
    ///   width: 10pX;
    /// }
    /// ```
    ///
    /// ```css
    /// a {
    ///   width: calc(10px + 10px);
    /// }
    /// ```
    ///
    pub NoUnknownUnit {
        version: "next",
        name: "noUnknownUnit",
        recommended: true,
        sources: &[RuleSource::Stylelint("unit-no-unknown")],
    }
}

impl Rule for NoUnknownUnit {
    type Query = Ast<AnyCssDimension>;
    type State = RuleState;
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
        let node = ctx.query();

        let unit_token = match node {
            // Any dimension whose unit is not a known CSS unit is always invalid.
            AnyCssDimension::CssUnknownDimension(dimension) => dimension.unit_token().ok()?,
            AnyCssDimension::CssRegularDimension(dimension) => {
                let unit_token = dimension.unit_token().ok()?;

                // `x` is a resolution unit (an alias of `dppx`). It's a known unit,
                // but it's only valid within a resolution context, such as inside
                // `image-set()` or the `resolution` media feature. In any other
                // context it's most likely a typo and should be reported.
                if !unit_token.text_trimmed().eq_ignore_ascii_case("x") {
                    return None;
                }

                if is_in_resolution_context(node) {
                    return None;
                }

                unit_token
            }
            // A percentage is always a valid dimension.
            AnyCssDimension::CssPercentage(_) => return None,
        };

        Some(RuleState {
            unit: unit_token.text_trimmed().to_string(),
            span: unit_token.text_trimmed_range(),
        })
    }

    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                state.span,
                markup! {
                    "Unexpected unknown unit: "{ state.unit }
                },
            )
            .note(markup! {
                <Hyperlink href="https://developer.mozilla.org/en-US/docs/Learn/CSS/Building_blocks/Values_and_units#lengths">"See MDN web docs for more details."</Hyperlink>
            })
            .footer_list(
                markup! {
                    "Use a known unit instead, such as:"
                },
                &["px", "em", "rem", "etc."],
            ),
        )
    }
}

pub struct RuleState {
    unit: String,
    span: TextRange,
}

/// Returns `true` when the given dimension appears in a context where the `x`
/// resolution unit is valid, i.e. within an `image-set()` (or the vendor
/// prefixed `-webkit-image-set()`) function, the `resolution` media feature, or
/// the `image-resolution` property.
fn is_in_resolution_context(node: &AnyCssDimension) -> bool {
    for ancestor in node.syntax().ancestors() {
        match ancestor.kind() {
            CssSyntaxKind::CSS_FUNCTION => {
                if let Some(function) = CssFunction::cast(ancestor) {
                    if let Ok(name) = function.name() {
                        let name = name.text().to_lowercase();
                        if name == "image-set" || name == "-webkit-image-set" {
                            return true;
                        }
                    }
                }
            }
            CssSyntaxKind::CSS_QUERY_FEATURE_PLAIN => {
                if let Some(feature) = CssQueryFeaturePlain::cast(ancestor) {
                    if let Ok(name) = feature.name() {
                        if name.text().to_lowercase() == "resolution" {
                            return true;
                        }
                    }
                }
            }
            CssSyntaxKind::CSS_GENERIC_PROPERTY => {
                if let Some(property) = CssGenericProperty::cast(ancestor) {
                    if let Ok(name) = property.name() {
                        if name.text().to_lowercase() == "image-resolution" {
                            return true;
                        }
                    }
                }
            }
            _ => {}
        }
    }

    false
}
